episodes.settled_cypher:
MATCH (a:Account {_workspace_id: $workspace_id})
MATCH (b:Account {_workspace_id: $workspace_id})
WHERE a.acct_no < b.acct_no
// transfer either direction
WITH a,b
WHERE EXISTS { MATCH (a)-[:TRANSFER]->(b) } OR EXISTS { MATCH (b)-[:TRANSFER]->(a) }
// owners
MATCH (ownerA)-[:OWN]->(a)
MATCH (ownerB)-[:OWN]->(b)
WHERE ownerA <> ownerB
// guarantee either direction between owners
WITH a,b,ownerA,ownerB
WHERE EXISTS { MATCH (ownerA)-[:GUARANTEE]->(ownerB) } OR EXISTS { MATCH (ownerB)-[:GUARANTEE]->(ownerA) }
// same device signed in to both accounts
MATCH (m:Medium {_workspace_id: $workspace_id})-[:SIGN_IN]->(a)
MATCH (m)-[:SIGN_IN]->(b)
RETURN a.acct_no AS acct_a, b.acct_no AS acct_b
LIMIT $limit

